void restart_mab(kissat *solver) {
    // Constants for the algorithm
    #define ALPHA_FAST 0.20
    #define ALPHA_SLOW 0.05
    #define ALPHA_VOL 0.10
    #define DECAY_SLOW_INACTIVE 0.99
    #define DECAY_GLOBAL_INACTIVE 0.01
    #define Q_COEFF 0.1
    #define TEMP_BASE 0.1
    #define MOMENTUM_IMPROVING 0.10
    #define MOMENTUM_DEGRADING -0.15
    #define STREAK_LIMIT 5

    // Persistent state for MAB tracking
    static double fast_ema[32];
    static double slow_ema[32];
    static double volatility[32];
    static uint64_t inactivity_age[32];
    static uint64_t active_streak[32];
    static uint64_t total_intervals = 0;
    static double global_yield_sum = 0;
    static bool initialized = false;

    unsigned num_h = solver->mab_heuristics;
    if (num_h == 0) return;
    if (num_h > 32) num_h = 32;

    unsigned h = solver->heuristic;
    if (h >= num_h) h = 0;

    // Step 1: Calculate the current interval's Yield Y
    // Y = (conflicts / (decisions + 1)) * (global_avg_LBD / (1.0 + local_avg_LBD))
    double conflicts = (double)solver->mab_conflicts;
    double decisions = (double)solver->mab_decisions;
    double global_lbd = AVERAGE(slow_glue);
    double local_lbd = AVERAGE(fast_glue);
    double Y = (conflicts / (decisions + 1.0)) * (global_lbd / (1.0 + local_lbd));

    // Initialization check to prevent zero-bias
    if (!initialized) {
        for (unsigned i = 0; i < 32; i++) {
            fast_ema[i] = Y;
            slow_ema[i] = Y;
            volatility[i] = 0.0;
            inactivity_age[i] = 0;
            active_streak[i] = 0;
        }
        initialized = true;
    }

    // Update global tracking
    total_intervals++;
    global_yield_sum += Y;
    double global_avg_yield = global_yield_sum / (double)total_intervals;

    // Step 2: Update the active mode's Fast EMA, Slow EMA, Relative Momentum, and Volatility
    fast_ema[h] = (ALPHA_FAST * Y) + ((1.0 - ALPHA_FAST) * fast_ema[h]);
    slow_ema[h] = (ALPHA_SLOW * Y) + ((1.0 - ALPHA_SLOW) * slow_ema[h]);

    double m_rel = (fast_ema[h] - slow_ema[h]) / (slow_ema[h] + 1e-6);
    double diff = Y - fast_ema[h];
    if (diff < 0) diff = -diff;
    volatility[h] = (ALPHA_VOL * diff) + ((1.0 - ALPHA_VOL) * volatility[h]);

    active_streak[h]++;
    inactivity_age[h] = 0;

    // Step 3: For the inactive modes, apply soft decay and increment inactivity age
    for (unsigned i = 0; i < num_h; i++) {
        if (i != h) {
            slow_ema[i] = (DECAY_SLOW_INACTIVE * slow_ema[i]) + (DECAY_GLOBAL_INACTIVE * global_avg_yield);
            inactivity_age[i]++;
            active_streak[i] = 0;
        }
    }

    // Step 4 & 5: Gating Logic and Boltzmann Selection
    unsigned next_h = h;
    if (m_rel > MOMENTUM_IMPROVING) {
        // Improving: Deterministically keep current mode
        next_h = h;
    } else if (m_rel < MOMENTUM_DEGRADING && active_streak[h] > STREAK_LIMIT) {
        // Degrading: Deterministically switch to the other mode
        next_h = (h + 1) % num_h;
    } else {
        // Stagnant or low-streak transition: Adaptive Boltzmann Selection
        double Q[32];
        double q_max = -1e30;
        double T = TEMP_BASE + volatility[h];

        // Calculate Quality Q_m for all modes
        for (unsigned i = 0; i < num_h; i++) {
            Q[i] = fast_ema[i] + Q_COEFF * sqrt(log((double)total_intervals) / (1.0 + (double)inactivity_age[i]));
            if (Q[i] > q_max) q_max = Q[i];
        }

        // Calculate Softmax probabilities
        double sum_exp = 0;
        for (unsigned i = 0; i < num_h; i++) {
            sum_exp += exp((Q[i] - q_max) / T);
        }

        // Stochastic selection based on P(m)
        double r = kissat_pick_double(&solver->random);
        double acc = 0;
        next_h = num_h - 1; // Fallback
        for (unsigned i = 0; i < num_h; i++) {
            double p = exp((Q[i] - q_max) / T) / sum_exp;
            acc += p;
            if (r < acc) {
                next_h = i;
                break;
            }
        }
    }

    // Apply the selection
    solver->heuristic = next_h;
    solver->mab_select[next_h]++;

    // Standard Kissat Housekeeping: Reset MAB interval counters
    solver->mab_conflicts = 0;
    solver->mab_decisions = 0;
    solver->mab_chosen_tot = 0;
    unsigned idx;
    for (all_variables(idx)) {
        solver->mab_chosen[idx] = 0;
    }
}

