void restart_mab(kissat *solver) {
    // Step 1: Track phase metrics and EMA-based statistics
    static double best_lbd = 1e100;
    static unsigned best_assigned_trail = 0xFFFFFFFF;
    static int stagnation_counter = 0;
    static int phases_since_switch = 0;
    static double mu_LBD = 0.0;
    static double prev_LBD = 0.0;
    static double V = 0.0;

    const double alpha = 0.1;
    const double beta = 0.9;

    double avg_lbd = AVERAGE(fast_glue);
    if (avg_lbd < 1.0) avg_lbd = 1.0;

    // Track global records and stagnation
    bool improved = false;
    if (avg_lbd < best_lbd) {
        best_lbd = avg_lbd;
        improved = true;
    }
    if (solver->unassigned < best_assigned_trail) {
        best_assigned_trail = solver->unassigned;
        improved = true;
    }

    if (!improved) {
        stagnation_counter++;
    }

    // Update global mean LBD using EMA
    if (mu_LBD == 0.0) {
        mu_LBD = avg_lbd;
    } else {
        mu_LBD = (beta * mu_LBD) + (alpha * avg_lbd);
    }

    // Step 2: Calculate phase reward R and update Quality Q_m
    double rate = (solver->mab_decisions > 0) ? (double)solver->mab_conflicts / (double)solver->mab_decisions : 0.0;
    double R = rate / (avg_lbd + 5.0);

    // Apply Global Progress Multiplier
    if (improved) {
        R *= 1.5;
    } else {
        R *= 0.8;
    }

    // Update current mode's Quality Q_m using EMA
    unsigned m = solver->heuristic;
    solver->mab_reward[m] = (beta * solver->mab_reward[m]) + (alpha * R);

    // Step 3: Compute scale-invariant momentum and search volatility
    if (prev_LBD == 0.0) {
        prev_LBD = avg_lbd;
    }
    double S_norm = (avg_lbd - prev_LBD) / (mu_LBD > 1e-6 ? mu_LBD : 1.0);
    prev_LBD = avg_lbd;

    // Calculate search volatility V as EMA of absolute deviation of S_norm
    V = (beta * V) + (alpha * fabs(S_norm));

    // Step 4: Execute Decision Gating
    phases_since_switch++;
    unsigned next_m = m;
    bool boltzmann_active = false;

    if (phases_since_switch < 3) {
        // (a) Maintain current mode
        next_m = m;
    } else if (S_norm < -0.05) {
        // (b) Improving: maintain current mode
        next_m = m;
    } else if (S_norm > 0.05 && (double)stagnation_counter > (5.0 + log10((double)solver->vars))) {
        // (c) Degrading and stagnating: force switch
        next_m = (m + 1) % solver->mab_heuristics;
    } else if (fabs(S_norm) <= 0.05) {
        // Step 5: Stagnation detected, apply Adaptive Boltzmann Selection
        boltzmann_active = true;
    }

    if (boltzmann_active) {
        double T = 0.1 + V;
        double max_q_scaled = -1e100;

        // Find max exponent for numerical stability
        for (unsigned i = 0; i < solver->mab_heuristics; i++) {
            double val = solver->mab_reward[i] / T;
            if (val > max_q_scaled) max_q_scaled = val;
        }

        double sum_exp = 0.0;
        for (unsigned i = 0; i < solver->mab_heuristics; i++) {
            sum_exp += exp((solver->mab_reward[i] / T) - max_q_scaled);
        }

        if (sum_exp > 0) {
            double r = kissat_pick_double(&solver->random);
            double cumulative_p = 0.0;
            for (unsigned i = 0; i < solver->mab_heuristics; i++) {
                double p = exp((solver->mab_reward[i] / T) - max_q_scaled) / sum_exp;
                cumulative_p += p;
                if (r < cumulative_p) {
                    next_m = i;
                    break;
                }
            }
        }
    }

    // Reset stagnation_counter and phases_since_switch upon any mode switch
    if (next_m != m) {
        stagnation_counter = 0;
        phases_since_switch = 0;
        solver->heuristic = next_m;
    }

    // Update selection count for the chosen heuristic
    solver->mab_select[solver->heuristic]++;

    // Reset per-variable MAB data and phase counters for the next phase
    unsigned idx;
    for (all_variables(idx)) {
        solver->mab_chosen[idx] = 0;
    }
    solver->mab_chosen_tot = 0;
    solver->mab_decisions = 0;
    solver->mab_conflicts = 0;
}

