#include <math.h>
#include <stdbool.h>
#include <stdint.h>
#include <inttypes.h>

#define MAB_ALPHA_FAST 0.20
#define MAB_ALPHA_SLOW 0.05
#define MAB_ALPHA_VOL 0.10
#define MAB_ALPHA_GLOB 0.05
#define MAB_DECAY_INACTIVE 0.98
#define MAB_DECAY_GLOB 0.02
#define MAB_EPSILON 1e-9

void restart_mab(kissat *solver) {
    // Persistent state for the MAB strategy
    static double fast_ema[2] = {0.0, 0.0};
    static double slow_ema[2] = {0.0, 0.0};
    static double volatility[2] = {0.0, 0.0};
    static double e_glob = 0.0;
    static uint64_t inactivity_age[2] = {0, 0};
    static uint64_t active_intervals[2] = {0, 0};
    static uint64_t total_intervals = 0;
    static bool initialized = false;

    // Step 1: Calculate the local performance metric Y
    // Y = log10(1.0 + (solver->conflicts / solver->ticks) * 1e6) * (global_average_LBD / (current_restart_LBD + 1.0))
    const double global_avg_lbd = AVERAGE(slow_glue);
    const double current_restart_lbd = AVERAGE(fast_glue);
    const double yield_y = log10(1.0 + ((double)CONFLICTS / (double)(solver->ticks + 1)) * 1000000.0) * 
                           (global_avg_lbd / (current_restart_lbd + 1.0));

    // Identify current mode (active) and other mode (inactive)
    unsigned h = solver->heuristic;
    if (h > 1) h = 0; // Binary choice safety
    unsigned other = 1 - h;

    // Handle initialization to prevent zero-bias
    if (!initialized) {
        fast_ema[0] = fast_ema[1] = yield_y;
        slow_ema[0] = slow_ema[1] = yield_y;
        e_glob = yield_y;
        initialized = true;
    }

    // Step 2: Update Active Mode Metrics
    double old_fast = fast_ema[h];
    fast_ema[h] = (1.0 - MAB_ALPHA_FAST) * fast_ema[h] + MAB_ALPHA_FAST * yield_y;
    slow_ema[h] = (1.0 - MAB_ALPHA_SLOW) * slow_ema[h] + MAB_ALPHA_SLOW * yield_y;
    // Volatility V = EMA(|Y - Fast_EMA|, alpha=0.10)
    volatility[h] = (1.0 - MAB_ALPHA_VOL) * volatility[h] + MAB_ALPHA_VOL * fabs(yield_y - old_fast);
    // Update Global EMA (E_glob)
    e_glob = (1.0 - MAB_ALPHA_GLOB) * e_glob + MAB_ALPHA_GLOB * yield_y;
    // Increment counters
    active_intervals[h]++;
    total_intervals++;

    // Step 3: Update Inactive Mode (Soft Decay)
    // E_fast_inactive = (0.98 * E_fast_inactive) + (0.02 * E_glob)
    fast_ema[other] = (MAB_DECAY_INACTIVE * fast_ema[other]) + (MAB_DECAY_GLOB * e_glob);
    inactivity_age[other]++;
    active_intervals[other] = 0; // Reset active streak for inactive mode

    // Step 4: Compute Relative Momentum M and apply Three-State Gating
    // M = (Fast_EMA - Slow_EMA) / (Slow_EMA + 1e-9)
    const double momentum_m = (fast_ema[h] - slow_ema[h]) / (slow_ema[h] + MAB_EPSILON);
    unsigned next_h = h;

    if (momentum_m > 0.05) {
        // [Improving]: Stay in the current mode
        next_h = h;
    } else if (momentum_m < -0.20 && active_intervals[h] > 5) {
        // [Degrading]: Switch to the other mode immediately
        next_h = other;
    } else {
        // Step 5: [Stagnant]: Proceed to Boltzmann Selection
        // Temperature T = 0.1 + (V / (Fast_EMA + 1e-9))
        const double temp_t = 0.1 + (volatility[h] / (fast_ema[h] + MAB_EPSILON));

        // Calculate scores
        const double s_active = fast_ema[h];
        const double s_inactive = fast_ema[other] + 
                                  (0.1 * sqrt((double)inactivity_age[other] / (double)total_intervals)) - 
                                  (0.05 * e_glob);

        // Softmax Selection
        const double v_act = s_active / temp_t;
        const double v_inact = s_inactive / temp_t;
        const double v_max = (v_act > v_inact) ? v_act : v_inact;
        const double exp_act = exp(v_act - v_max);
        const double exp_inact = exp(v_inact - v_max);
        const double prob_act = exp_act / (exp_act + exp_inact);

        if (kissat_pick_double(&solver->random) < prob_act) {
            next_h = h;
        } else {
            next_h = other;
        }
    }

    // Reset inactivity_age for the selected mode
    inactivity_age[next_h] = 0;

    // Apply heuristic selection and update Kissat statistics
    solver->heuristic = next_h;
    solver->mab_select[next_h]++;

    // Standard Kissat MAB Housekeeping: Reset interval counters
    solver->mab_conflicts = 0;
    solver->mab_decisions = 0;
    solver->mab_chosen_tot = 0;
    for (all_variables(idx)) {
        solver->mab_chosen[idx] = 0;
    }
}

