#include "restart.h"
#include "backtrack.h"
#include "bump.h"
#include "decide.h"
#include "internal.h"
#include "kimits.h"
#include "logging.h"
#include "print.h"
#include "reluctant.h"
#include "report.h"

#include <inttypes.h>
#include <math.h>
#include <stdbool.h>
#include <stdint.h>

#define MAB_ALPHA_FAST 0.2
#define MAB_ALPHA_SLOW 0.05
#define MAB_ALPHA_VOL 0.1
#define MAB_M_THRESHOLD 0.05
#define MAB_M_PROB_SCALE 2.5
#define MAB_PENALTY 0.95
#define MAB_T_BASE 0.1
#define MAB_EPSILON 1e-6

void restart_mab (kissat *solver) {
  // Step 1: Calculate the responsive performance metric P
  // P = (conflicts / decisions) * (1.0 / (avg_LBD_current_restart + 1.0))
  const double conflicts = (double) solver->mab_conflicts;
  const double decisions = (double) solver->mab_decisions;
  const double avg_lbd = AVERAGE (fast_glue);
  const double P =
      (decisions > 0) ? (conflicts / decisions) * (1.0 / (avg_lbd + 1.0)) : 0.0;

  // Step 2: Update state for the active mode
  // Using static arrays to persist EMA values as the kissat struct is fixed.
  static double e_fast[2] = {0.0, 0.0};
  static double e_slow[2] = {0.0, 0.0};
  static double volatility[2] = {0.0, 0.0};
  static bool initialized[2] = {false, false};

  const unsigned active = solver->heuristic;
  const unsigned other = 1 - active;

  if (active >= 2)
    return;

  if (!initialized[active]) {
    e_fast[active] = P;
    e_slow[active] = P;
    volatility[active] = 0.0;
    initialized[active] = true;
  } else {
    e_fast[active] =
        (1.0 - MAB_ALPHA_FAST) * e_fast[active] + MAB_ALPHA_FAST * P;
    e_slow[active] =
        (1.0 - MAB_ALPHA_SLOW) * e_slow[active] + MAB_ALPHA_SLOW * P;
    volatility[active] = (1.0 - MAB_ALPHA_VOL) * volatility[active] +
                         MAB_ALPHA_VOL * fabs (P - e_fast[active]);
  }

  // Update reward for visibility/logging
  solver->mab_reward[active] = e_fast[active];

  // Step 3: Compute Relative Momentum M
  const double M = (e_fast[active] - e_slow[active]) / (e_slow[active] + MAB_EPSILON);

  unsigned next_m = active;

  // Step 4: Apply Trajectory Gating
  if (M > MAB_M_THRESHOLD) {
    // Improving: deterministically stay in current mode
    next_m = active;
  } else if (M < -MAB_M_THRESHOLD) {
    // Degrading: check if other mode is better
    if (initialized[other] && e_fast[active] < (e_fast[other] * MAB_PENALTY)) {
      double prob = fabs (M) * MAB_M_PROB_SCALE;
      if (prob > 1.0)
        prob = 1.0;
      if (kissat_pick_double (&solver->random) < prob) {
        next_m = other;
      }
    }
  } else {
    // Step 5: Hysteresis-Boltzmann Selection (|M| <= 0.05)
    // If the other mode isn't initialized, we alternate to gather data
    if (!initialized[other]) {
      next_m = other;
    } else {
      const double T = MAB_T_BASE + (volatility[active] / (e_fast[active] + MAB_EPSILON));
      const double Q_active = e_fast[active];
      const double Q_inactive = e_fast[other] * MAB_PENALTY;

      // Numerical stability: max-subtraction
      const double v_act = Q_active / T;
      const double v_inact = Q_inactive / T;
      const double max_v = (v_act > v_inact) ? v_act : v_inact;

      const double exp_act = exp (v_act - max_v);
      const double exp_inact = exp (v_inact - max_v);
      const double sum_exp = exp_act + exp_inact;

      if (sum_exp > 0) {
        const double prob_active = exp_act / sum_exp;
        if (kissat_pick_double (&solver->random) >= prob_active) {
          next_m = other;
        }
      }
    }
  }

  // Apply selection and reset counters
  solver->heuristic = next_m;
  solver->mab_select[next_m]++;
  solver->mab_decisions = 0;
  solver->mab_conflicts = 0;

  // Reset per-variable tracking if heuristic changed
  if (next_m != active) {
    for (unsigned i = 0; i < solver->vars; i++) {
      solver->mab_chosen[i] = 0;
    }
    solver->mab_chosen_tot = 0;
  }
}

