void restart_mab(kissat *solver) {
    // Step 0: Persistent state for EMAs, history, and timing
    static double S_fast[2] = {0.0, 0.0};
    static double S_slow[2] = {0.0, 0.0};
    static bool ema_init[2] = {false, false};

    static double history[10] = {0.0};
    static unsigned history_idx = 0;
    static unsigned history_count = 0;

    static uint64_t consecutive_count = 0;
    static uint64_t last_ticks = 0;
    static bool ticks_init = false;

    // Safety check for Kissat MAB heuristics (typically 0 and 1)
    if (solver->mab_heuristics < 2) return;
    unsigned mode = solver->heuristic;
    if (mode >= 2) return;

    // Step 1: Compute the restart reward R
    const uint64_t conflicts = solver->mab_conflicts;
    const uint64_t current_ticks = solver->ticks;
    if (!ticks_init) {
        last_ticks = current_ticks;
        ticks_init = true;
    }
    const uint64_t elapsed_ticks = (current_ticks > last_ticks) ? (current_ticks - last_ticks) : 0;
    last_ticks = current_ticks;

    const double avg_lbd = AVERAGE(fast_glue);
    const double avg_trail = AVERAGE(level);
    const double avg_trail_adj = (avg_trail < 0.0) ? 0.0 : avg_trail;

    // R = (conflicts * 10000) / ((elapsed_ticks + 1) * (avg_LBD + log2(avg_trail_level + 1) + 1))
    const double num = (double)conflicts * 10000.0;
    const double den = ((double)elapsed_ticks + 1.0) * (avg_lbd + log2(avg_trail_adj + 1.0) + 1.0);
    const double R = (den > 0.0) ? (num / den) : 0.0;

    // Step 2: Update dual EMAs for the active mode and apply Benchmark Decay for inactive
    if (!ema_init[mode]) {
        S_fast[mode] = S_slow[mode] = R;
        ema_init[mode] = true;
    } else {
        S_fast[mode] = 0.8 * S_fast[mode] + 0.2 * R;
        S_slow[mode] = 0.95 * S_slow[mode] + 0.05 * R;
    }

    for (unsigned i = 0; i < solver->mab_heuristics; i++) {
        if (i != mode) {
            S_slow[i] *= 0.998; // Benchmark Decay
        }
    }

    // Step 3: Calculate relative performance trend S_rel and search volatility V
    history[history_idx] = R;
    history_idx = (history_idx + 1) % 10;
    if (history_count < 10) history_count++;

    double mean = 0.0;
    for (unsigned i = 0; i < history_count; i++) mean += history[i];
    mean /= (double)history_count;

    double variance = 0.0;
    for (unsigned i = 0; i < history_count; i++) {
        double diff = history[i] - mean;
        variance += diff * diff;
    }
    double std_dev = sqrt(variance / (double)history_count);
    double V = std_dev / (mean + 1e-9);
    double S_rel = (S_fast[mode] - S_slow[mode]) / (S_slow[mode] + 1e-9);

    // Step 4: Calculate the Fatigue-Adjusted Score S_adj
    double S_adj = S_fast[mode] * pow(0.998, (double)consecutive_count);

    // Step 5 & 6: Selection with Hysteresis, Momentum Override, and Probabilistic Switching
    bool switch_mode = false;
    unsigned other = 1 - mode;
    double S_slow_other = S_slow[other];

    if (consecutive_count < 20) {
        // Hysteresis: return current mode (switch_mode remains false)
    } else if (S_rel > 0.1) {
        // Momentum Override: return current mode (switch_mode remains false)
    } else {
        // Execute selection
        // (a) Deterministic switch for underperformance
        if (S_adj < S_slow_other && S_rel < 0.0) {
            switch_mode = true;
        } 
        // (b) Probabilistic switch for significant decay
        else if (S_rel < -0.05) {
            double P = 1.0 / (1.0 + exp((S_adj - S_slow_other) / ((0.1 + V) * S_slow[mode] + 1e-9)));
            if (kissat_pick_double(&solver->random) < P) {
                switch_mode = true;
            }
        }
    }

    // Apply selection and update consecutive_count
    if (switch_mode) {
        solver->heuristic = other;
        consecutive_count = 0;
    } else {
        consecutive_count++;
    }

    // Reset MAB tracking counters for the next phase
    solver->mab_conflicts = 0;
    solver->mab_decisions = 0;
    solver->mab_chosen_tot = 0;
    for (all_variables(idx)) {
        solver->mab_chosen[idx] = 0;
    }
}
